INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Prüfung 1: Planen eines Softwareprodukts > Datenschutz > Grundsätze (Art. 5) > Vertraulichkeit
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Fordert der Grundsatz der Vertraulichkeit gemäß Art. 5 DSGVO, dass personenbezogene Daten vor unbefugtem Zugriff geschützt werden?', 2, '[{"text": "Ja", "correct": true, "because": "Art. 5 Abs. 1f verlangt Schutz vor unbefugter Verarbeitung"}, {"text": "Nein", "correct": false, "because": "Vertraulichkeit ist zwingend"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann die Vertraulichkeit nach Art. 5 DSGVO ohne technische Schutzmaßnahmen gewährleistet werden?', 2, '[{"text": "Nein", "correct": true, "because": "Technische und organisatorische Maßnahmen sind erforderlich"}, {"text": "Ja", "correct": false, "because": "Ohne Schutzmaßnahmen fehlt Sicherheit"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Daten gemäß dem Vertraulichkeitsgrundsatz immer verschlüsselt sein?', 2, '[{"text": "Nein", "correct": true, "because": "Verschlüsselung ist ein Mittel, aber nicht zwingend"}, {"text": "Ja", "correct": false, "because": "Andere Maßnahmen möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Verstöße gegen den Grundsatz der Vertraulichkeit zu Bußgeldern führen?', 2, '[{"text": "Ja", "correct": true, "because": "Verstöße gegen Art. 5 können sanktioniert werden"}, {"text": "Nein", "correct": false, "because": "Bußgelder sind vorgesehen"}]'),
('00000000-0000-0000-0000-000000000000', 'Ist die Vertraulichkeit nach Art. 5 DSGVO nur für digitale Daten relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Gilt für alle personenbezogenen Daten"}, {"text": "Ja", "correct": false, "because": "Auch papierbasierte Daten betroffen"}]'),

-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Was bedeutet der Grundsatz der Vertraulichkeit gemäß Art. 5 DSGVO?', 2, '[{"text": "Schutz vor unbefugtem Zugriff", "correct": true, "because": "Art. 5 Abs. 1f schützt Datenintegrität und Vertraulichkeit"}, {"text": "Maximale Datenerhebung", "correct": false, "because": "Widerspricht DSGVO"}, {"text": "Schnelle Datenverarbeitung", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahme stellt die Vertraulichkeit nach Art. 5 DSGVO am effektivsten sicher?', 3, '[{"text": "Verschlüsselung", "correct": true, "because": "Schützt Daten vor unbefugtem Zugriff"}, {"text": "Regelmäßige Backups", "correct": false, "because": "Schützt vor Verlust, nicht Zugriff"}, {"text": "Datensparsamkeit", "correct": false, "because": "Anderer Grundsatz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Anforderung ist zentral für den Grundsatz der Vertraulichkeit?', 2, '[{"text": "Technische und organisatorische Maßnahmen", "correct": true, "because": "Art. 5 Abs. 1f fordert Schutzmaßnahmen"}, {"text": "Maximale Datenfreigabe", "correct": false, "because": "Widerspricht Vertraulichkeit"}, {"text": "Hohe Verarbeitungsgeschwindigkeit", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Konsequenz droht bei Verstoß gegen den Grundsatz der Vertraulichkeit?', 2, '[{"text": "Bußgelder", "correct": true, "because": "Verstoß gegen Art. 5 strafbar"}, {"text": "Systemstilllegung", "correct": false, "because": "Keine Standardstrafe"}, {"text": "Geringere Nutzerfreundlichkeit", "correct": false, "because": "Indirekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Aspekt der Vertraulichkeit ist für die Softwareplanung am wichtigsten?', 2, '[{"text": "Datensicherheit durch Design", "correct": true, "because": "Privacy by Design schützt Vertraulichkeit"}, {"text": "Hohe Datenmenge", "correct": false, "because": "Widerspricht Minimierung"}, {"text": "Schnelle Datenübertragung", "correct": false, "because": "Kein Schutzfaktor"}]'),

-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Anforderungen stellt der Grundsatz der Vertraulichkeit nach Art. 5 DSGVO?', 4, '[{"text": "Schutz vor unbefugtem Zugriff", "correct": true, "because": "Kern der Vertraulichkeit"}, {"text": "Integrität der Daten", "correct": true, "because": "Schutz vor Veränderung"}, {"text": "Technische Maßnahmen", "correct": true, "because": "Erforderlich für Sicherheit"}, {"text": "Öffentliche Datenfreigabe", "correct": false, "because": "Widerspricht Vertraulichkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen unterstützen die Vertraulichkeit nach Art. 5 DSGVO?', 3, '[{"text": "Verschlüsselung", "correct": true, "because": "Schützt Daten vor Zugriff"}, {"text": "Zugriffskontrollen", "correct": true, "because": "Beschränkt Berechtigungen"}, {"text": "Audit-Logs", "correct": true, "because": "Nachverfolgbarkeit von Zugriffen"}, {"text": "Unbeschränkter Zugriff", "correct": false, "because": "Verstoß gegen Vertraulichkeit"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Bedrohungen gefährden die Vertraulichkeit?', 4, '[{"text": "Unbefugter Zugriff", "correct": true, "because": "Direkte Verletzung"}, {"text": "Datenlecks", "correct": true, "because": "Offenlegung sensibler Daten"}, {"text": "Hacking", "correct": true, "because": "Technischer Angriff"}, {"text": "Langsame Server", "correct": false, "because": "Kein Vertraulichkeitsrisiko"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Folgen kann ein Verstoß gegen den Grundsatz der Vertraulichkeit haben?', 3, '[{"text": "Bußgelder", "correct": true, "because": "Verstoß gegen Art. 5 strafbar"}, {"text": "Schadensersatz", "correct": true, "because": "Betroffene können klagen"}, {"text": "Vertrauensverlust", "correct": true, "because": "Kundenvertrauen schwindet"}, {"text": "Schnellere Verarbeitung", "correct": false, "because": "Keine Folge"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Prinzipien der DSGVO ergänzen die Vertraulichkeit?', 3, '[{"text": "Datenminimierung", "correct": true, "because": "Weniger Daten, weniger Risiko"}, {"text": "Richtigkeit", "correct": true, "because": "Korrekte Daten schützen Vertrauen"}, {"text": "Integrität", "correct": true, "because": "Schutz vor Manipulation"}, {"text": "Maximale Datensammlung", "correct": false, "because": "Widerspricht DSGVO"}]'),

-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Vertraulichkeit schützt vor unbefugtem Zugriff. b) Sie kann ohne Schutzmaßnahmen gewährleistet werden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schutz ja, Maßnahmen nötig"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Verschlüsselung unterstützt die Vertraulichkeit. b) Sie gilt nur für digitale Daten.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Verschlüsselung ja, auch papierbasierte Daten"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Verstöße gegen Vertraulichkeit können Bußgelder nach sich ziehen. b) Verschlüsselung ist immer erforderlich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Bußgelder ja, Verschlüsselung optional"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Zugriffskontrollen fördern die Vertraulichkeit. b) Vertraulichkeit schützt nur vor externen Bedrohungen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Kontrollen ja, interne Bedrohungen auch"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Datenschutz durch Technik unterstützt Vertraulichkeit. b) Vertraulichkeit ist ohne Integrität möglich.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Technik ja, Integrität ergänzend"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

